constexpr std::uint64_t EncodeSubtag(const wchar_t* value, std::uint16_t characterBits)
{
    std::uint64_t key = 0;
    while (*value != L'\0')
    {
        key <<= characterBits;

        const std::uint16_t character = *value++;
        if (static_cast<std::uint16_t>(character - L'0') <= 9)
        {
            if (characterBits == 3)
            {
                characterBits = 4;
                key = 16;
            }

            key += character - L'0' + 1;
        }
        else
        {
            if (characterBits == 3)
            {
                characterBits = 5;
            }

            key += static_cast<std::uint64_t>(character >= L'a' ? character - L'`' : character - L'@');
        }
    }

    return key;
}

constexpr std::uint16_t EncodeRegionTag(const wchar_t* value, const bool hasReplacement = false)
{
    return static_cast<std::uint16_t>((EncodeSubtag(value, 3) << 1) | hasReplacement);
}

constexpr std::uint16_t EncodeLanguageTag(const wchar_t* value, const bool hasReplacement = false)
{
    return static_cast<std::uint16_t>((EncodeSubtag(value, 5) << 1) | hasReplacement);
}

constexpr std::uint32_t EncodeScriptTag(const wchar_t* value) { return static_cast<std::uint32_t>(EncodeSubtag(value, 5)); }
